head.script:
// 담당 범위 : navBtn 가이드 전 항목 (con_navBtn 1개)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > navBtn]<br/>inputType='checkcombobox' 인 Column 에서 아이템 리스트창 하단에 '선택적용', '선택해제' 버튼을 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시, 아이템 리스트창 하단에 '선택적용', '선택해제' 버튼을 표시합니다.",
        "true 설정 시, '선택적용' : 버튼 클릭 시 선택한 아이템을 Cell 에 반영하고 아이템 리스트창을 닫습니다.",
        "true 설정 시, '선택해제' : 버튼 클릭 시 아이템 리스트창의 모든 아이템 선택을 해제하며 아이템 리스트창은 닫히지 않습니다.",
        "false 설정 시, 아이템 리스트창 하단에 버튼을 표시하지 않습니다.",
        "미설정 시, 아이템 리스트창 하단에 버튼을 표시하지 않습니다.",
        "'선택해제' 버튼으로 해제한 내용은 아이템 리스트창을 닫거나 '선택적용' 버튼을 클릭하면 Cell 에 반영됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (true)
    con_navBtn.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 1월 ~ 5월 (value 1 ~ 5), 리스트창 기본 표시 행 수 이내라 스크롤 없이 버튼 영역까지 표시
scwin.itemCount = 5;
scwin.rowData = [
    { "name" : "선택 없음", "month" : "" },
    { "name" : "1월 ~ 3월 선택", "month" : "1 2 3" }
];



// comp 생성
//  - name  : 초기 선택 상태 설명 Column
//  - month : 검증 대상 Body Column (inputType=checkcombobox, 아이템 1월 ~ 5월, navBtn = con_navBtn)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] month 셀 더블클릭으로 아이템 리스트창 열기 -> 아이템 클릭 -> 선택적용 클릭\n[선택해제] 1행 리스트창에서 선택해제 클릭 -> 리스트창 유지 확인 -> 리스트창 밖(결과창) 클릭 또는 선택적용 클릭\n[확인] 편집 종료(리스트창 닫힘) 시 출력되는 선택값"', '', 'label1');

    // 조건 설정 (gdl_boolean -> getText, 미설정은 속성 자체를 넣지 않는다)
    let cNavBtn = con_navBtn.getText();

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (선택값 구분자는 기본 공백)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="month" name="month" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowData, false);

    // 아이템 정의
    let strItems = '<w2:choices>';
    for (let i = 1; i <= scwin.itemCount; i++) {
        strItems += '<w2:item><w2:label>' + i + '월</w2:label><w2:value>' + i + '</w2:value></w2:item>';
    }
    strItems += '</w2:choices>';

    // month Column 속성
    let attrMonth = ' inputType="checkcombobox"';
    attrMonth += (cNavBtn === '') ? '' : ' navBtn="' + cNavBtn + '"';

    // 이벤트 바인딩 (편집 종료 시 선택값 출력)
    let eList = $c.gcm.createEList(["oneditend"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" id="" style="width:600px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column1" value="초기 선택 상태"></w2:column>';
    strTarget += '<w2:column width="360" style="" inputType="text" id="column2" value="month (checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="220" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="360" style="text-align:left;" id="month" value=""' + attrMonth + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 2, 3, 6 판정 출력 : 편집 종료(리스트창 닫힘) 후 해당 행 선택값 / Cell 표시값
//  (validation 1, 4, 5 의 버튼 표시 여부와 validation 3 의 리스트창 유지는 화면에서 확인)
scwin.target1_oneditend = function (rowIndex, colIndex) {
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("편집 종료 후 " + rowIndex + "행 선택값 : '" + dlt_bind.getCellData(rowIndex, "month") + "' / Cell 표시 : '" + target1.getCellDisplayData(rowIndex, "month") + "'");
    }, 100);
}
